import {readFileSync, writeFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {createRequire} from 'node:module';
import {execFileSync} from 'node:child_process';
import path from 'node:path';

const hub='/data/qiwei/repos/omne-harness-lite/.worktrees/core-delivery';
const source='/data/qiwei/repos/omne-harness-lite/.worktrees/minimal-runtime';
const out=hub+'/tmp/core-delivery/util-reuse-audit.json';
const names=['unix-format','xml-format','timeout','brand'];
const require=createRequire(hub+'/packages/core/identity-values/package.json');
const ts=require('typescript');
const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
const git=(cwd,args)=>execFileSync('git',args,{cwd,encoding:'utf8'}).trim();
const snapshot={source:{root:source,branch:git(source,['branch','--show-current']),commit:git(source,['rev-parse','HEAD']),status:git(source,['status','--short'])},hub:{root:hub,branch:git(hub,['branch','--show-current']),commit:git(hub,['rev-parse','HEAD']),status:git(hub,['status','--short'])}};
const packages={};
for(const name of names){
  const prefix='packages/util/'+name+'/';
  const files=git(source,['ls-files','--',prefix]).split('\n').filter(Boolean).map(file=>{
    const bytes=readFileSync(source+'/'+file);
    const head=execFileSync('git',['show','HEAD:'+file],{cwd:source});
    return {path:file,bytes:bytes.length,sha256:sha(bytes),headBlobSha256:sha(head),matchesHead:bytes.equals(head)};
  });
  const manifest=JSON.parse(readFileSync(source+'/'+prefix+'package.json','utf8'));
  const provenance=JSON.parse(readFileSync(source+'/'+prefix+'provenance.json','utf8'));
  const goldenFile=files.find(f=>f.path.endsWith('/golden.json'));
  const golden=goldenFile?JSON.parse(readFileSync(source+'/'+goldenFile.path,'utf8')):undefined;
  packages[name]={manifest,provenance,files,tests:files.filter(f=>/\/tests\//.test(f.path)).map(f=>f.path),goldenShape:golden?Object.fromEntries(Object.entries(golden).map(([k,v])=>[k,{kind:Array.isArray(v)?'array':typeof v,count:typeof v==='object'&&v!==null?Object.keys(v).length:undefined}])):null};
}
const loaderCache=new Map();
function moduleUrl(file,root){
  const resolved=path.resolve(file);
  if(!resolved.startsWith(path.resolve(root)+'/')) throw new Error('module outside selected root: '+resolved);
  if(loaderCache.has(resolved)) return loaderCache.get(resolved);
  const sourceText=readFileSync(resolved,'utf8');
  const result=ts.transpileModule(sourceText,{compilerOptions:{target:ts.ScriptTarget.ES2024,module:ts.ModuleKind.ESNext},reportDiagnostics:true});
  if(result.diagnostics?.some(d=>d.category===ts.DiagnosticCategory.Error)) throw new Error('transpile errors '+resolved);
  const js=result.outputText.replace(/(from\s+|import\s*)(['"])(\.[^'"]+)\2/g,(all,prefix,quote,specifier)=>{
    const imported=path.resolve(path.dirname(resolved),specifier.replace(/\.(js|ts)$/,'.ts'));
    return prefix+quote+moduleUrl(imported,root)+quote;
  });
  const url='data:text/javascript;base64,'+Buffer.from(js).toString('base64');
  loaderCache.set(resolved,url);
  return url;
}
const unix=await import(moduleUrl(source+'/packages/util/unix-format/src/index.ts',source+'/packages/util/unix-format'));
const xml=await import(moduleUrl(source+'/packages/util/xml-format/src/index.ts',source+'/packages/util/xml-format'));
const timeout=await import(moduleUrl(source+'/packages/util/timeout/src/index.ts',source+'/packages/util/timeout'));
const brand=await import(moduleUrl(source+'/packages/util/brand/src/index.ts',source+'/packages/util/brand'));
const measurements=[];
function measure(id,input,fn,sourceOracle){
  try { const value=fn(); measurements.push({id,input,status:'returned',output:value,oracle:sourceOracle});}
  catch(error){measurements.push({id,input,status:'threw',error:{name:error.name,message:error.message},oracle:sourceOracle});}
}
measure('unix.negativeStart',{lines:['x'],start:-1},()=>unix.formatNumberedLines(['x'],{start:-1}),'README states negative start throws; source numbered.ts only requires integer; report mismatch, do not set new policy.');
measure('unix.codePointTruncation',{lines:['😀a'],perLineCharLimit:1},()=>unix.formatNumberedLines(['😀a'],{perLineCharLimit:1}),'Source numbered.ts uses Array.from-based code-point slicing.');
measure('unix.commandDelimiter',{commands:[['go','','desc']]},()=>unix.formatCommandList([['go','','desc']]),'Public CommandEntry is readonly [name,synopsis,description]; README plain ASCII claim checked against em dash separator in sections.ts.');
measure('unix.tableBestEffortCap',{headers:['verylong','z'],rows:[['verylong','z']],maxWidth:5},()=>unix.formatTable(['verylong','z'],[['verylong','z']],{maxWidth:5}),'README documents best-effort cap; only last column shrinks.');
measure('xml.nameFinalNewline',{name:'a\n'},()=>xml.isXmlName('a\n'),'Existing options.spec.ts rejects final newline; static suspicion is explicitly checked, false means no defect.');
measure('xml.plainMarkupEscaped',{x:'</x><bad/>'},()=>xml.formatXml({x:'</x><bad/>'},{tag:'root',requiredFields:{x:{}}}),'README escaping promise for ordinary strings.');
measure('xml.rawSelfRendering',{toXmlReturn:'</root><bad/>'},()=>xml.formatXml({x:{toXml(){return '</root><bad/>';}}},{tag:'root',requiredFields:{x:{}}}),'format.ts intentionally embeds XmlFormattable raw; document trusted callback boundary.');
measure('xml.duplicateAttribute',{x:'one',manualAttributes:{x:'two'}},()=>xml.formatXml({x:'one'},{tag:'root',requiredFields:{x:{presentation:'attr'}}},{manualAttributes:{x:'two'}}),'assemble appends manual attributes after rendered attributes; no uniqueness check.');
measure('xml.nullCharacter',{x:'\u0000'},()=>xml.formatXml({x:'\u0000'},{tag:'root',requiredFields:{x:{}}}),'escape.ts replaces markup delimiters only; XML legal-character validation not implemented.');
measure('xml.entityIsPlainText',{input:'&amp;'},()=>xml.escapeXmlContent('&amp;'),'Existing options.spec.ts explicitly expects &amp;amp; despite test title.');
measure('timeout.invalidRequested',{requested:0,default:10,max:100},()=>timeout.clampTimeout(0,10,100),'Existing support.spec.ts asserts requested zero throws.');
measure('timeout.invalidDefault',{requested:null,default:-1,max:100},()=>timeout.clampTimeout(undefined,-1,100),'Implementation validates only requested when present; callers own valid default/max.');
measure('timeout.invalidMax',{requested:10,default:20,max:-1},()=>timeout.clampTimeout(10,20,-1),'Implementation validates only requested when present; callers own valid default/max.');
measure('timeout.noTimerDeadline',{timeoutMs:0},()=>{const upstream=new AbortController().signal;const result=timeout.deadline(upstream,0,'probe');const same=result.signal===upstream;result[Symbol.dispose]();return {sameUpstreamSignal:same,aborted:result.signal.aborted};},'deadline timeoutMs<=0 path is documented no timer; no positive deadline or runtime stopping tested.');
measure('brand.emptyString',{value:''},()=>({same:brand.brandString('')==='',value:brand.brandString('')}),'brandString applies type assertion only; cannot replace opaque identifier admission.');
measure('brand.nanNumber',{value:'NaN'},()=>({sameNaN:Number.isNaN(brand.brandNumber(NaN))}),'brandNumber applies type assertion only; cannot replace numeric validation.');

const base=ts.readConfigFile(hub+'/tsconfig.base.json',ts.sys.readFile);
const parsed=ts.parseJsonConfigFileContent(base.config,ts.sys,hub);
const nodeTypes=path.dirname(path.dirname(require.resolve('@types/node/package.json')));
const compilerOptions={...parsed.options,noEmit:true,types:['node'],typeRoots:[nodeTypes],allowImportingTsExtensions:true,rootDir:undefined};
function diagnostics(program){
  return ts.getPreEmitDiagnostics(program).map(d=>{
    const position=d.file&&d.start!==undefined?d.file.getLineAndCharacterOfPosition(d.start):null;
    return {code:d.code,category:ts.DiagnosticCategory[d.category],file:d.file?.fileName,line:position?position.line+1:null,column:position?position.character+1:null,message:ts.flattenDiagnosticMessageText(d.messageText,'\n')};
  });
}
const compatibility={options:compilerOptions,packages:{}};
for(const name of names){
  const roots=packages[name].files.filter(f=>/\/src\/.*\.ts$/.test(f.path)).map(f=>source+'/'+f.path);
  const host=ts.createCompilerHost(compilerOptions);
  host.writeFile=()=>{throw new Error('write forbidden during noEmit audit');};
  const program=ts.createProgram(roots,compilerOptions,host);
  compatibility.packages[name]={mode:'TypeScript createProgram with current HUB base strict flags; source read only; noEmit; no package/public consumer build',diagnostics:diagnostics(program)};
}
const virtualFile=hub+'/tmp/core-delivery/__virtual_brand_comparison__.ts';
const virtualSource="import type { Branded as SourceBranded } from '"+source+"/packages/util/brand/src/index.ts';\nimport type { Branded as HubBranded } from '"+hub+"/packages/core/identity-values/src/opaque.ts';\ndeclare const sourceValue: SourceBranded<'ExampleId'>;\ndeclare const hubValue: HubBranded<string, 'ExampleId'>;\nconst asHub: HubBranded<string,'ExampleId'> = sourceValue;\nconst asSource: SourceBranded<'ExampleId'> = hubValue;\n";
const host=ts.createCompilerHost(compilerOptions);
const original=host.getSourceFile.bind(host);
host.getSourceFile=(file,languageVersion,...args)=>file===virtualFile?ts.createSourceFile(file,virtualSource,languageVersion,true):original(file,languageVersion,...args);
host.fileExists=file=>file===virtualFile||ts.sys.fileExists(file);
host.readFile=file=>file===virtualFile?virtualSource:ts.sys.readFile(file);
host.writeFile=()=>{throw new Error('write forbidden during virtual brand audit');};
compatibility.brandInterchangeability={source:virtualSource,diagnostics:diagnostics(ts.createProgram([virtualFile],compilerOptions,host)),scope:'Exact source package brand versus current HUB identity-values brand. Does not test duplicate installation or compiler package-id deduplication.'};
const official=[];
for(const name of ['timeout','brand']){
  const provenance=packages[name].provenance;
  for(const entry of provenance.files){
    if(official.some(item=>item.upstreamPath===entry.upstream_path)) continue;
    const url='https://raw.githubusercontent.com/deepseek-ai/deepseek-harness/'+provenance.commit+'/'+entry.upstream_path;
    const response=await fetch(url);
    const bytes=Buffer.from(await response.arrayBuffer());
    official.push({url,status:response.status,upstreamCommit:provenance.commit,upstreamPath:entry.upstream_path,bytes:bytes.length,sha256:sha(bytes),declaredSha256:entry.sha256,matchesDeclared:response.ok&&sha(bytes)===entry.sha256});
  }
}
const hubRelevant=['packages/AGENTS.md','packages/README.md','package.json','pnpm-workspace.yaml','tsconfig.base.json','packages/core/identity-values/src/opaque.ts','packages/core/content-blocks/src/json.ts','.meta_harness/design/realization/README.md','.meta_harness/design/realization/packages/core/tool-definition/design.md'];
const hubInputs=hubRelevant.map(file=>{const bytes=readFileSync(hub+'/'+file);return {path:file,sha256:sha(bytes)};});
const audit={format:1,task:'Read-only utility reuse audit; no package implementation; no design acceptance',capturedAt:new Date().toISOString(),environment:{node:process.version,typescript:ts.version,compiler:require.resolve('typescript'),platform:process.platform,architecture:process.arch},snapshot,packages,measurements,compatibility,official,hubInputs,limitations:['Did not run source workspace builds, Vitest suites, Python golden generation, install dependencies, or alter source tree.','Readonly in-memory transpilation is a targeted behavior observation, not a product consumer build.','MIT upstream individual file hashes verified; provenance archive hash not downloaded or verified.','omne-next origin commit/path and historical Python runs are local provenance claims; original Python checkout not independently inspected.','No real positive timeout, timeout workload cancellation, iterator disposal or resource cleanup measured.','No design or source acceptance conferred by this audit.']};
writeFileSync(out,JSON.stringify(audit,null,2)+'\n');
console.log(JSON.stringify({artifact:out,sourceFiles:Object.values(packages).reduce((n,p)=>n+p.files.length,0),allSourceFilesMatchHead:Object.values(packages).every(p=>p.files.every(f=>f.matchesHead)),measurements,compatibility:Object.fromEntries(Object.entries(compatibility.packages).map(([k,v])=>[k,v.diagnostics])),brandDiagnostics:compatibility.brandInterchangeability.diagnostics,official},null,2));
